 if(from){const lm=lr?meta(lr):null;const usable=lr&&lm?.start?balances(it.id,from)-reserved(it.id,from,lm.start,lm.end,lr.id):available(it.id,from);guard(q<=usable+1e-7,'الكمية تتجاوز المتاح بعد استبعاد الحجوزات.');}
