 const m={id:uid('MOVE'),number:next('MOV',db().movements),type,itemId:it.id,qty:q,from,to,date,employeeId:T(data.employeeId),employeeName:emp(data.employeeId)?.name||'',party:T(data.party),reason:T(data.reason),condition:T(data.condition)||'سليم',authorization:T(data.authorization),dueDate:validDate(data.dueDate),refMoveId:T(data.refMoveId),logisticsId:T(data.logisticsId),purchaseId:T(data.purchaseId),receiptId:T(data.receiptId),purchaseLineId:T(data.purchaseLineId),at:now(),by:me(),byId:myid()};db().movements.push(m);audit('stock',m.id,MT[type]+' '+q+' '+it.unit+' — '+it.name);syncAssets();return m;
