function modal(title,body,foot='',context=null){if(!Q('o18Modal'))modalFocus=document.activeElement;Q('o18Modal')?.remove();D=context;const root=document.createElement('div');root.id='o18Modal';root.className='o18 o18-modal-back';root.innerHTML='<section class="o18-dialog" role="dialog" aria-modal="true" aria-labelledby="o18Title"><header><div><small>MOSH GROUP · التشغيل</small><h2 id="o18Title">'+E(title)+'</h2></div>'+btn('×','close','','icon','aria-label="إغلاق"')+'</header><div class="o18-dialog-body">'+body+'</div><footer>'+foot+btn('إلغاء / إغلاق','close')+'</footer></section>';document.body.append(root);root.querySelector('input,select,button')?.focus();root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const els=[...root.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(x=>x.offsetParent);if(els.length&&((e.shiftKey&&document.activeElement===els[0])||(!e.shiftKey&&document.activeElement===els.at(-1)))){e.preventDefault();(e.shiftKey?els.at(-1):els[0]).focus();}}});}
function ask(text){return new Promise(resolve=>{const r=document.createElement('div');r.className='o18 o18-modal-back o18-confirm';r.innerHTML='<section class="o18-dialog"><header><h2>تأكيد الإجراء</h2></header><div class="o18-dialog-body">'+E(text)+'</div><footer><button class="o18-btn" data-answer="no">إلغاء</button><button class="o18-btn primary" data-answer="yes">تأكيد</button></footer></section>';document.body.append(r);r.querySelector('button').focus();r.addEventListener('click',e=>{const x=e.target.closest('[data-answer]');if(x){r.remove();resolve(x.dataset.answer==='yes');}});});}
