function table(headers,body){return '<div class="o18-table"><table><thead><tr>'+headers.map(h=>'<th>'+E(h)+'</th>').join('')+'</tr></thead><tbody>'+ (body||'<tr><td colspan="'+headers.length+'"><div class="o18-empty">لا توجد سجلات ضمن هذا الاختيار.</div></td></tr>')+'</tbody></table></div>';}
function paged(key,rows,headers,row){const max=Math.max(1,Math.ceil(rows.length/12));U.pages[key]=Math.min(max,Math.max(1,U.pages[key]||1));const p=U.pages[key];return table(headers,rows.slice((p-1)*12,p*12).map(row).join(''))+'<div class="o18-pager"><span>'+rows.length+' سجل · صفحة '+p+' من '+max+'</span><div>'+btn('السابق','page',key+'|'+(p-1),'',p===1?'disabled':'')+btn('التالي','page',key+'|'+(p+1),'',p===max?'disabled':'')+'</div></div>';}
