async function cleanupFiles(keys){if(!keys.length)return;try{const db0=await openAttachmentsDB();await new Promise((resolve,reject)=>{const tx0=db0.transaction(ATTACHMENTS_STORE,'readwrite');keys.forEach(k=>tx0.objectStore(ATTACHMENTS_STORE).delete(k));tx0.oncomplete=resolve;tx0.onerror=()=>reject(tx0.error);});db0.close();}catch(e){/* Unreferenced file cleanup must never erase committed attachments. */}}
