function scanSync(){if(Q('o35ScanWH'))U.scanWarehouse=val('o35ScanWH');if(Q('o35ScanEmployee'))U.scanEmployee=val('o35ScanEmployee');if(Q('o35ScanParty'))U.scanParty=val('o35ScanParty');if(Q('o35ScanLog'))U.scanLogistics=val('o35ScanLog');if(Q('o35ScanDue'))U.scanDue=val('o35ScanDue');if(Q('o35ScanAuthorization'))U.scanAuthorization=val('o35ScanAuthorization');if(Q('o35ScanReason'))U.scanReason=val('o35ScanReason');Q('o35ScanCart')?.querySelectorAll('[data-o35-line]').forEach(r=>{const x=A(U.scanCart).find(v=>v.itemId===r.dataset.o35Line);if(x){const q=Number(r.querySelector('[data-o35-qty]')?.value);if(Number.isFinite(q)&&q>0)x.qty=q;}});}
function scanFocus(){setTimeout(()=>Q('o35BarcodeInput')?.focus(),30);}
function scanAdd(code=''){scanSync();guard(U.scanWarehouse,'اختر المستودع المصدر أولاً.');const raw=T(code||val('o35BarcodeInput'));guard(raw,'امسح الباركود أو اكتبه.');const it=barcodeItem(raw);guard(it&&it.active!==false,'لم يتم العثور على صنف بهذا الباركود / الكود. أضف الباركود إلى بطاقة الصنف أولاً.');const avail=available(it.id,U.scanWarehouse);guard(avail>0,'لا يوجد رصيد متاح من '+it.name+' في المستودع المختار.');let row=A(U.scanCart).find(x=>x.itemId===it.id);if(row){guard(it.tracking!=='serial','الأصل المرقم موجود في السلة مسبقاً.');row.qty=round(Number(row.qty||0)+1);guard(row.qty<=avail+1e-7,'الكمية في السلة تتجاوز المتاح من '+it.name+'.');}else U.scanCart.push({itemId:it.id,qty:1});openArea('warehouses','scan');scanFocus();}
function scanPage(){const wh=warehouse(U.scanWarehouse),cart=A(U.scanCart).filter(x=>item(x.itemId)),hasIssue=cart.some(x=>item(x.itemId)?.tracking!=='consumable'),hasConsume=cart.some(x=>item(x.itemId)?.tracking==='consumable'),total=cart.reduce((n,x)=>n+Number(x.qty||0),0);const rows=cart.map(x=>{const it=item(x.itemId),avail=U.scanWarehouse?available(it.id,U.scanWarehouse):0;return '<tr data-o35-line="'+E(it.id)+'"><td><b>'+E(it.name)+'</b><small>'+E(it.sku)+(it.barcode?' · '+E(it.barcode):'')+'</small></td><td>'+E(it.tracking==='consumable'?'صرف استهلاكي':'تسليم عهدة')+'</td><td>'+avail+' '+E(it.unit)+'</td><td><input class="o35-qty" data-o35-qty type="number" min="0.000001" step="any" value="'+E(x.qty)+'" '+(it.tracking==='serial'?'readonly':'')+'></td><td>'+btn('حذف','barcode-remove',it.id,'danger')+'</td></tr>';}).join('');
 return head('تشغيل سريع','الصرف بالباركود','اختر المستودع مرة واحدة، ثم امسح الباركود. قارئ الباركود يعمل مثل لوحة المفاتيح ويضيف الصنف عند Enter.',btn('الأصناف والأرصدة','nav','warehouses|stock')+btn('سجل الحركات','nav','warehouses|movements'))+
 '<section class="o18-card o35-scan-panel"><div class="o35-scan-top">'+select('المستودع المصدر *','o35ScanWH',warehouseOptions(),U.scanWarehouse)+'</div><div class="o35-scan-box"><label for="o35BarcodeInput">امسح الباركود</label><div><input id="o35BarcodeInput" inputmode="numeric" autocomplete="off" placeholder="ضع المؤشر هنا وامسح الباركود ثم Enter"><button type="button" class="o18-btn primary" data-o18="barcode-add">إضافة للسلة</button></div><small>يمكن أيضاً إدخال كود الصنف أو الرقم التسلسلي عند الحاجة.</small></div>'+(wh?'<div class="o35-scan-status"><span>المستودع: <b>'+E(wh.name)+'</b></span><span>أصناف بالسلة: <b>'+cart.length+'</b></span><span>إجمالي الكمية: <b>'+total+'</b></span></div>':'')+'</section>'+
 '<section class="o18-card"><div class="o18-heading"><div><h3>سلة الصرف</h3><p>راجع الكمية قبل الاعتماد. الأصل ذو الرقم التسلسلي يبقى قطعة واحدة.</p></div><div class="o18-actions">'+(cart.length?btn('تفريغ السلة','barcode-clear','','danger'):'')+'</div></div>'+table(['الصنف / الباركود','نوع الحركة','المتاح','الكمية',''],rows)+'</section>'+
 '<section class="o18-card"><div class="o18-heading"><div><h3>بيانات التسليم</h3><p>النظام يختار نوع الحركة تلقائياً: العهد للأصول، والصرف للمواد الاستهلاكية.</p></div></div><div class="o18-grid">'+select('الموظف المستلم'+(hasIssue?' *':''),'o35ScanEmployee',personOptions(),U.scanEmployee)+input('الجهة / المستلم','o35ScanParty',U.scanParty)+select('طلب لوجستي مرتبط','o35ScanLog',[['','غير مرتبط'],...A(state.supportRequests).filter(r=>r.type==='logistics'&&!['cancelled','completed'].includes(phase(r))).map(r=>[r.id,r.requestNo+' · '+(r.title||r.logisticsType)])],U.scanLogistics)+dateInput('موعد إعادة العهدة','o35ScanDue',U.scanDue)+input('مرجع موافقة العميل على الاستهلاك','o35ScanAuthorization',U.scanAuthorization)+ta('سبب / ملاحظة الصرف','o35ScanReason',U.scanReason)+'</div>'+(hasIssue?'<p class="o18-note">السلة تحتوي عهداً قابلة للإرجاع؛ يجب تحديد الموظف المستلم.</p>':'')+(hasConsume?'<p class="o18-muted">المواد الاستهلاكية ستخرج نهائياً من الرصيد عند الاعتماد.</p>':'')+'<div class="o35-scan-submit">'+btn('اعتماد صرف '+cart.length+' صنف','barcode-save','','primary',cart.length&&U.scanWarehouse?'':'disabled')+'</div></section>';
}
async function scanSave(){scanSync();guard(U.scanWarehouse,'اختر المستودع المصدر.');const cart=A(U.scanCart).filter(x=>item(x.itemId));guard(cart.length,'السلة فارغة.');const issue=cart.filter(x=>item(x.itemId).tracking!=='consumable'),consume=cart.filter(x=>item(x.itemId).tracking==='consumable');if(issue.length)guard(emp(U.scanEmployee),'اختر الموظف المستلم للعهدة.');if(consume.length)guard(T(U.scanParty)||emp(U.scanEmployee)||T(U.scanReason),'اكتب الجهة المستلمة أو سبب الصرف.');cart.forEach(x=>{const it=item(x.itemId),q=checkQty(it,x.qty);guard(q<=available(it.id,U.scanWarehouse)+1e-7,'الكمية تتجاوز المتاح من '+it.name+'.');if(it.owner==='customer'&&it.tracking==='consumable')guard(T(U.scanAuthorization),'أدخل مرجع موافقة العميل لاستهلاك '+it.name+'.');});const result=await tx(()=>{cart.forEach(x=>{const it=item(x.itemId),type=it.tracking==='consumable'?'consume':'issue';moveStock({type,itemId:it.id,qty:x.qty,from:U.scanWarehouse,date:today(),employeeId:type==='issue'?U.scanEmployee:'',party:U.scanParty||emp(U.scanEmployee)?.name||'',logisticsId:U.scanLogistics,dueDate:type==='issue'?U.scanDue:'',authorization:type==='consume'?U.scanAuthorization:'',condition:'سليم',reason:'صرف بالباركود'+(T(U.scanReason)?' — '+T(U.scanReason):'')});});},'تم اعتماد الصرف بالباركود وتحديث الرصيد.');if(result.ok){U.scanCart=[];U.scanAuthorization='';U.scanReason='';openArea('warehouses','scan');scanFocus();}}
