 const global=document.querySelector('.sidebar .nav')||document.querySelector('.nav');if(global&&!Q('o18WarehousesNav')){const a=document.createElement('a');a.id='o18WarehousesNav';a.href='#';a.title='المستودعات العامة';a.dataset.o18='nav';a.dataset.value='warehouses|home';a.innerHTML='<span class="nav-icon">'+icon('box')+'</span><span class="nav-label">المستودعات العامة</span>';const l=global.querySelector('[onclick*="goApp(\'logistics\'"]');if(l)l.after(a);else global.append(a);}
