 MoshUI15.tabState(area,'');mark(area,view);const page=Q('o18Page_'+area);page.hidden=false;current={area,view,id:''};
 if(view==='exec'){openDeptExecReportStep3(area,areaNames[area]);return;}
 let html='';
 if(['requests','orders','schedule'].includes(view))html=listPage(area,view);
 else if(view==='suppliers'){guard(isBuyer());html=suppliersPage();}
 else if(view==='warehouses'){guard(canStock());html=warehouseHome();}
 else if(view==='inbound'){guard(canStock());html=inboundPage();}
 else if(view==='scan'){guard(canStock());html=scanPage();scanFocus();}
 else if(view==='stock'||view==='customers'){guard(canStock());if(view==='customers')U.stockOwner='customer';else if(U.stockOwner==='customer')U.stockOwner='all';html=stockPage();}
 else if(view==='movements'){guard(canStock());html=head('سجل المستودعات','سجل الحركات','استلام، تسليم، نقل وإرجاع. كل حركة لها سند، ولا تختلط بجدول تنفيذ اللوجستيات.',btn('حركة جديدة','move-form','','primary'))+movementTable(db().movements.slice().reverse());}
 else if(view==='custody'||view==='overdue'){guard(canStock());html=custodyPage(view==='overdue');}
