function printOrder(id){const r=request(id);guard(mayView(r));const m=meta(r),q=m.approval?.quote;guard(q,'لا يوجد أمر معتمد.');printPreview('أمر شراء معتمد '+m.orderNo,'<p><b>حالة الأمر: '+E(P[m.phase]||m.phase)+'</b>'+(['cancelled','deferred','returned'].includes(m.phase)?' — هذا المستند غير صالح للتنفيذ في حالته الحالية.':'')+'</p><p>المورد: <b>'+E(q.supplierName)+'</b> · طلب '+E(r.requestNo)+'</p><p>القسم المستفيد: '+E(r.sourceDepartment)+' · مكان التسليم: '+E(r.location||'—')+'</p>'+table(['المادة / الخدمة','الوصف','الكمية','الوحدة','سعر الوحدة','خصم %','ضريبة %'],q.lines.map(l=>'<tr><td>'+E(l.name)+'</td><td>'+E(l.spec)+'</td><td>'+l.qty+'</td><td>'+E(l.unit)+'</td><td>'+cash(l.price,q.currency)+'</td><td>'+l.discount+'</td><td>'+l.tax+'</td></tr>').join(''))+'<h2>الإجمالي المعتمد '+cash(m.approval.total.total,q.currency)+'</h2><p>شروط الدفع: '+E(q.paymentTerms)+' · التوريد: '+q.deliveryDays+' يوم · الضمان: '+E(q.warranty||'—')+'</p><p>الاعتماد: '+E(m.approval.by)+' · '+E(stamp(m.approval.at))+' · '+E(m.approval.reason)+'</p><div class="o18-signatures"><span>المشتريات: __________________</span><span>المورد: __________________</span></div>');}
